var loaderScript = new GlideRecord('sys_dictionary');
loaderScript.addQuery('name', 'sys_data_source');
loaderScript.addQuery('element', 'data_loader');
loaderScript.query();

if (loaderScript.next()) {
    loaderScript.default_value = '(function loadData(import_set_table, data_source, import_log, last_success_import_time) {\n\n' +
		'     // Add your code here to insert data to import_set_table\n\n' + 
		'})(import_set_table, data_source, import_log, last_success_import_time);';
    loaderScript.update();
}
